ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    "message": "Product updated in inventory successfully",
    "productId": vars.requestParams.uriParams.productId,
    "updatedFields": [
        vars.requestParams.payload
    ]
}

%dw 2.0
output application/json
---
[
(vars.product[0] - "IsAvailable__c") ++ {
	IsAvailable__c: false
}
]

%dw 2.0
output application/json
---
{
	partner_id:payload[0].Id
}

json-logger:logger.json-logger:content:
#[%dw 2.0
output application/json
---
{
    logId: upper("log-order-status-bypass-transit-mismatch"),
    message: "Order status update bypassed due to destination–current city mismatch",
    details: {
        destinationCity: vars.transit[0].Destination_City__c default "UNKNOWN",
        currentCity: vars.requestParams.payload.currentCity default "UNKNOWN",
        orderId: vars.transit[0].Order_Id__c default "UNKNOWN"
    },
    status: "NO_ACTION_TAKEN"
}]

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    "message": "Transit record updated in inventory successfully",
    "transitId": vars.requestParams.uriParams.transitId,
    "updatedFields": [
        vars.requestParams.payload
    ]
}
